INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'yasmine@demo.ftour.invalid'), 'Premier soir de bénévolat hier, quelle ambiance ! 🌙 Merci à toute l''équipe de la cuisine, on a servi plus de 300 repas. Qui était là ?', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-4320 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'karim@demo.ftour.invalid'), 'Présent hier à l''accueil. Les familles étaient tellement reconnaissantes. On remet ça samedi ? Je prends le créneau 17h-20h.', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-4200 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'hajar@demo.ftour.invalid'), 'Le planning de la semaine prochaine est publié dans votre espace. Si un créneau ne vous convient pas, échangez avec quelqu''un directement ici plutôt que de ne pas venir, merci 🙏', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-3960 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'salma@demo.ftour.invalid'), 'Rappel amical : arrivez 30 minutes avant votre créneau pour le briefing, et pensez à votre badge. Merci à tous ! 💙', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-3600 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'mehdi@demo.ftour.invalid'), 'Astuce de cuisine : on gagne 15 minutes sur le montage des plateaux si on prépare les bacs de chorba la veille au soir. Qui est du matin samedi ?', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-3480 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'omar@demo.ftour.invalid'), 'Quelqu''un a des idées pour mieux organiser la distribution des dattes ? On a perdu un peu de temps hier au service.', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-3300 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'nadia@demo.ftour.invalid'), 'On pourrait préparer les barquettes de dattes en amont, par lots de 50. Je peux m''en occuper avant l''ouverture.', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-3000 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'karim@demo.ftour.invalid'), 'Une famille est arrivée hier avec cinq enfants et pas de réservation. On a trouvé de la place, mais pensez à rappeler aux gens de réserver à l''avance 😅', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-2760 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'imane@demo.ftour.invalid'), 'Petite question de débutante : on prend ses pauses où ? Et est-ce qu''on mange avec les convives ou après le service ?', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-2520 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'mehdi@demo.ftour.invalid'), 'On a besoin de renfort en cuisine jeudi soir, 2-3 personnes en plus. Qui est partant ?', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-2400 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'imane@demo.ftour.invalid'), 'Première fois que je fais du bénévolat et j''adore. Merci pour votre accueil, vraiment 🥹', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-2160 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'reda@demo.ftour.invalid'), 'Info pour les conducteurs : le parking devant la salle est plein dès 18h. Garez-vous plutôt dans la rue d''à côté, c''est à 3 minutes à pied.', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-1980 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'reda@demo.ftour.invalid'), 'Idée : un covoiturage entre bénévoles pour rentrer après le service ? Je passe par Maarif et Gauthier, 2 places libres.', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-1800 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'yasmine@demo.ftour.invalid'), 'Pour celles et ceux qui demandaient : oui, il y aura un petit moment pour la photo de l''équipe samedi avant le service. Venez avec le sourire !', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-1620 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'hajar@demo.ftour.invalid'), 'Merci à celles et ceux qui ont aidé à ranger hier soir. On a fini en 20 minutes grâce à vous ! 👏', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-1440 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'anas@demo.ftour.invalid'), 'Question pratique : où peut-on laisser nos affaires pendant le service ? Il y a un vestiaire ?', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-1200 minutes'));
INSERT INTO hub_posts (member_id, body, kind, pinned, status, created_at) VALUES ((SELECT id FROM hub_members WHERE email = 'omar@demo.ftour.invalid'), 'Bilan dattes : avec les lots de 50 de Nadia, la distribution est passée de 25 à 12 minutes. Merci ! Prochaine étape : le lait ribot, on s''y penche 😄', 'post', 0, 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-960 minutes'));
