INSERT INTO pro_comments (post_id, member_id, body, status, created_at) VALUES ((SELECT id FROM pro_posts WHERE member_id = (SELECT id FROM hub_members WHERE email = 'mehdi@demo.ftour.invalid') AND body = 'Je cherche un stage de fin d''études en logistique ou supply chain (4 à 6 mois, Casablanca ou Rabat). Mon bénévolat m''a appris à gérer des flux de repas en temps réel 😄 Si vous connaissez une équipe qui recrute, un message m''aide énormément.'), (SELECT id FROM hub_members WHERE email = 'reda@demo.ftour.invalid'), 'Bon courage Mehdi ! Pour un entretien de stage, prépare deux ou trois exemples chiffrés de ce que tu as organisé.', 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-4340 minutes'));
INSERT INTO pro_comments (post_id, member_id, body, status, created_at) VALUES ((SELECT id FROM pro_posts WHERE member_id = (SELECT id FROM hub_members WHERE email = 'reda@demo.ftour.invalid') AND body = 'J''ai quelques créneaux libres en livraison la semaine prochaine (Casablanca, voiture personnelle). Idéal pour commerçants ou petits producteurs.'), (SELECT id FROM hub_members WHERE email = 'omar@demo.ftour.invalid'), '@Reda je te mets en contact avec un traiteur du quartier, ils cherchent un livreur pour le week-end.', 'visible', strftime('%Y-%m-%dT%H:%M:%fZ','now','-2085 minutes'));
INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'salma@demo.ftour.invalid'), 'Animateur(trice) bénévole, ateliers jeunes', 'Association Exemple (fictive)', 'Casablanca', 'benevolat', 'Nous cherchons des animateurs pour des ateliers de soutien scolaire et de loisirs créatifs, un à deux après-midis par semaine. Aucune expérience exigée, un entretien d''accueil de 30 minutes suffit. Idéal pour un étudiant ou un lycéen motivé.', '+212000000003', 'open', strftime('%Y-%m-%dT%H:%M:%fZ','now','-4320 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-4320 minutes'));
INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'hajar@demo.ftour.invalid'), 'Stage RH, 4 mois', 'Groupe Exemple Fès (fictif)', 'Fès', 'stage', 'Stage en ressources humaines : planification des équipes, suivi des absences, accueil des nouveaux collaborateurs. Vous seconderez la responsable RH sur des missions concrètes. Niveau bac+3 minimum, bon relationnel et maîtrise d''Excel demandés.', '+212000000009', 'open', strftime('%Y-%m-%dT%H:%M:%fZ','now','-3600 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-3600 minutes'));
INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'nadia@demo.ftour.invalid'), 'Commis de pâtisserie', 'Pâtisserie Exemple (fictive)', 'Marrakech', 'cdi', 'Notre atelier de pâtisserie marocaine recrute un commis pour la préparation des gâteaux et la mise en boîte des commandes. Horaires du matin, du mardi au samedi. Formation en interne, nous cherchons surtout quelqu''un de soigneux et ponctuel.', '+212000000005', 'open', strftime('%Y-%m-%dT%H:%M:%fZ','now','-3240 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-3240 minutes'));
INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'omar@demo.ftour.invalid'), 'Préparateur(trice) de commandes, CDD saison', 'Transports Exemple (fictif)', 'Casablanca', 'cdd', 'Préparation et expédition de commandes dans un entrepôt, pour la période de forte activité. Le poste a été pourvu : merci à toutes les personnes qui ont candidaté. Nous gardons vos coordonnées pour la prochaine saison.', '+212000000004', 'closed', strftime('%Y-%m-%dT%H:%M:%fZ','now','-2880 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-2880 minutes'));
INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'yasmine@demo.ftour.invalid'), 'Assistant(e) événementiel, CDD de 3 mois', 'Atelier Horizon (fictif)', 'Casablanca', 'cdd', 'Vous assistez l''équipe sur la préparation et le déroulé d''événements : logistique, accueil des invités, suivi des prestataires. Disponibilité possible en soirée et le week-end. Une première expérience en accueil ou en bénévolat est un vrai plus.', '+212000000001', 'open', strftime('%Y-%m-%dT%H:%M:%fZ','now','-2640 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-2640 minutes'));
INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'reda@demo.ftour.invalid'), 'Livreur partenaire, remplacement d''été', 'Livraisons Exemple (fictif)', 'Casablanca', 'cdd', 'Remplacement de deux mois pour des livraisons de colis légers à Casablanca. Véhicule personnel requis. L''offre est désormais fermée, merci de votre intérêt.', '+212000000008', 'closed', strftime('%Y-%m-%dT%H:%M:%fZ','now','-2040 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-2040 minutes'));
INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'karim@demo.ftour.invalid'), 'Refonte d''un site vitrine, mission freelance de 3 semaines', 'Cabinet Exemple Conseil (fictif)', 'Rabat', 'freelance', 'Refonte d''un site vitrine d''une dizaine de pages pour une petite structure, avec un hébergement existant. Vous livrez un site simple à maintenir, avec un back-office de base. Budget à discuter selon votre expérience, contact téléphonique en priorité.', '+212000000002', 'open', strftime('%Y-%m-%dT%H:%M:%fZ','now','-1680 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-1680 minutes'));
INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'anas@demo.ftour.invalid'), 'Gagnez gros : assistant(e) à domicile', 'Entreprise Exemple (fictive)', 'Casablanca', 'freelance', 'Travaillez depuis chez vous, 5000 DH par jour garantis, aucune expérience demandée. Contactez-moi vite pour plus de détails.', '+212000000010', 'open', strftime('%Y-%m-%dT%H:%M:%fZ','now','-420 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-420 minutes'));
INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'salma@demo.ftour.invalid'), 'Photographe pour un événement associatif, mission d''une journée', 'Association Exemple (fictive)', 'Casablanca', 'freelance', 'Nous cherchons une personne à l''aise avec un appareil photo pour couvrir une journée de rencontre entre bénévoles : portraits, ambiance, moments clés. Livraison d''une sélection retouchée sous une semaine. Défraiement et repas prévus, contact téléphonique en priorité.', '+212000000003', 'open', strftime('%Y-%m-%dT%H:%M:%fZ','now','-300 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-300 minutes'));
