INSERT INTO mt_meetups (member_id, title, category, description, country, city, place, starts_at, ends_at, capacity, photo_key, status, cancelled_at, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'nadia@demo.ftour.invalid'), 'Randonnée dans la vallée de l''Ourika', 'sortie', 'Journée de marche douce le long de la rivière, avec pique-nique au bord des cascades. Environ 3 heures de marche au total, chaussures de sport conseillées. Co-voiturage depuis Marrakech possible, dites-le dans les commentaires du fil.', 'Maroc', 'Marrakech', 'Parking du village de Setti Fatma', (date('now','-12 days') || 'T08:30'), (date('now','-12 days') || 'T17:00'), 12, 'demo/meetup-randonnee-ourika.jpg', 'active', NULL, strftime('%Y-%m-%dT%H:%M:%fZ','now','-43200 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-43200 minutes'));
INSERT INTO mt_meetups (member_id, title, category, description, country, city, place, starts_at, ends_at, capacity, photo_key, status, cancelled_at, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'salma@demo.ftour.invalid'), 'Café de retrouvailles et bilan de la saison', 'rencontre', 'On se retrouve autour d''un thé pour faire le bilan de la saison, partager nos meilleurs souvenirs et recueillir vos idées pour l''an prochain. Aucune obligation de prendre la parole, venez simplement discuter.', 'Maroc', 'Casablanca', 'Café des Arcades, boulevard d''Anfa', (date('now','-6 days') || 'T16:00'), (date('now','-6 days') || 'T19:00'), 20, 'demo/meetup-cafe-casablanca.jpg', 'active', NULL, strftime('%Y-%m-%dT%H:%M:%fZ','now','-25920 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-25920 minutes'));
INSERT INTO mt_meetups (member_id, title, category, description, country, city, place, starts_at, ends_at, capacity, photo_key, status, cancelled_at, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'karim@demo.ftour.invalid'), 'Tournoi de foot entre bénévoles', 'evenement', 'Mini-tournoi amical à cinq contre cinq, ambiance détente. Les équipes sont tirées au sort sur place, apportez des baskets et une bouteille d''eau. Un goûter est prévu pour tout le monde à la fin.', 'Maroc', 'Rabat', 'Terrain de proximité, quartier Agdal', (date('now','-20 days') || 'T18:00'), (date('now','-20 days') || 'T20:30'), 10, 'demo/meetup-foot-rabat.jpg', 'active', NULL, strftime('%Y-%m-%dT%H:%M:%fZ','now','-57600 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-57600 minutes'));
INSERT INTO mt_meetups (member_id, title, category, description, country, city, place, starts_at, ends_at, capacity, photo_key, status, cancelled_at, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'mehdi@demo.ftour.invalid'), 'Petit-déjeuner marocain des bénévoles à Paris', 'rencontre', 'Pour les bénévoles qui vivent ou passent par Paris : msemen, baghrir et thé à la menthe pour retrouver l''esprit de l''équipe à distance. Venez avec vos idées pour rester en lien toute l''année.', 'France', 'Paris', 'Salon de thé La Menthe Fraîche, rue Oberkampf', (date('now','+7 days') || 'T10:00'), (date('now','+7 days') || 'T12:30'), 10, 'demo/meetup-petit-dej-paris.jpg', 'active', NULL, strftime('%Y-%m-%dT%H:%M:%fZ','now','-8640 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-8640 minutes'));
INSERT INTO mt_meetups (member_id, title, category, description, country, city, place, starts_at, ends_at, capacity, photo_key, status, cancelled_at, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'nadia@demo.ftour.invalid'), 'Atelier cuisine : msemen et tajine pour tous', 'evenement', 'On prépare ensemble des msemen puis un tajine de poulet aux olives, et on déguste à la fin. Tous niveaux, tablier fourni. Très demandé : si l''atelier est complet, inscrivez-vous sur la liste d''attente, les places libérées sont attribuées dans l''ordre.', 'Maroc', 'Marrakech', 'Dar Nadia, quartier Guéliz', (date('now','+4 days') || 'T15:00'), (date('now','+4 days') || 'T18:30'), 6, 'demo/meetup-atelier-cuisine.jpg', 'active', NULL, strftime('%Y-%m-%dT%H:%M:%fZ','now','-12960 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-12960 minutes'));
INSERT INTO mt_meetups (member_id, title, category, description, country, city, place, starts_at, ends_at, capacity, photo_key, status, cancelled_at, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'omar@demo.ftour.invalid'), 'Nettoyage de plage à Aïn Diab', 'evenement', 'Matinée citoyenne pour ramasser les déchets sur la plage, gants et sacs fournis. On termine par un petit-déjeuner partagé. Venez en famille, les enfants sont les bienvenus.', 'Maroc', 'Casablanca', 'Plage d''Aïn Diab, devant la Corniche', (date('now','+9 days') || 'T09:00'), (date('now','+9 days') || 'T12:30'), 40, 'demo/meetup-plage-propre.jpg', 'active', NULL, strftime('%Y-%m-%dT%H:%M:%fZ','now','-7200 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-7200 minutes'));
INSERT INTO mt_meetups (member_id, title, category, description, country, city, place, starts_at, ends_at, capacity, photo_key, status, cancelled_at, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'yasmine@demo.ftour.invalid'), 'Soirée jeux de société et thé à la menthe', 'rencontre', 'Une soirée détendue entre bénévoles de la diaspora autour de jeux de société, de thé et de gâteaux. Apportez votre jeu préféré si vous en avez un. Entrée libre dans la limite des places.', 'Belgique', 'Bruxelles', 'Maison de quartier d''Ixelles, salle polyvalente', (date('now','+6 days') || 'T19:30'), (date('now','+6 days') || 'T23:00'), 12, 'demo/meetup-jeux-bruxelles.jpg', 'active', NULL, strftime('%Y-%m-%dT%H:%M:%fZ','now','-11520 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-11520 minutes'));
INSERT INTO mt_meetups (member_id, title, category, description, country, city, place, starts_at, ends_at, capacity, photo_key, status, cancelled_at, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'reda@demo.ftour.invalid'), 'Brunch de rentrée des bénévoles à Lyon', 'rencontre', 'Brunch convivial pour se retrouver à la rentrée et accueillir les nouveaux. Chacun apporte un plat à partager, salé ou sucré. On prévoit quelques options sans gluten.', 'France', 'Lyon', 'Péniche Le Bahut, quai Saint-Antoine', (date('now','+14 days') || 'T11:00'), (date('now','+14 days') || 'T14:30'), 15, NULL, 'active', NULL, strftime('%Y-%m-%dT%H:%M:%fZ','now','-5760 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-5760 minutes'));
INSERT INTO mt_meetups (member_id, title, category, description, country, city, place, starts_at, ends_at, capacity, photo_key, status, cancelled_at, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'hajar@demo.ftour.invalid'), 'Marche et photos dans la médina de Fès', 'sortie', 'Balade guidée par des habitués dans les ruelles de la médina, avec des arrêts photo et une pause thé. Prévoyez des chaussures confortables et un petit budget pour les achats.', 'Maroc', 'Fès', 'Rendez-vous à Bab Boujloud', (date('now','+11 days') || 'T09:30'), (date('now','+11 days') || 'T13:00'), 10, 'demo/meetup-medina-fes.jpg', 'active', NULL, strftime('%Y-%m-%dT%H:%M:%fZ','now','-10080 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-10080 minutes'));
INSERT INTO mt_meetups (member_id, title, category, description, country, city, place, starts_at, ends_at, capacity, photo_key, status, cancelled_at, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'imane@demo.ftour.invalid'), 'Rencontre des bénévoles de la diaspora à Montréal', 'rencontre', 'Premier rendez-vous des bénévoles installés au Canada ou de passage : on fait connaissance, on parle de nos souvenirs de la saison et de comment aider à distance. Boissons chaudes sur place.', 'Canada', 'Montréal', 'Café Atlas, Plateau-Mont-Royal', (date('now','+18 days') || 'T14:00'), (date('now','+18 days') || 'T17:00'), 25, 'demo/meetup-diaspora-montreal.jpg', 'active', NULL, strftime('%Y-%m-%dT%H:%M:%fZ','now','-4320 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-4320 minutes'));
INSERT INTO mt_meetups (member_id, title, category, description, country, city, place, starts_at, ends_at, capacity, photo_key, status, cancelled_at, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'karim@demo.ftour.invalid'), 'Sortie vélo sur la corniche de Rabat', 'sortie', 'Balade à vélo tranquille le long de la corniche, environ 15 km aller-retour. Annulée : une alerte météo annonce du vent fort et de la pluie ce jour-là. Nous proposerons une nouvelle date bientôt.', 'Maroc', 'Rabat', 'Plage de Rabat, esplanade', (date('now','+3 days') || 'T08:00'), (date('now','+3 days') || 'T11:00'), 15, 'demo/meetup-velo-corniche.jpg', 'cancelled', strftime('%Y-%m-%dT%H:%M:%fZ','now','-11520 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-14400 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-14400 minutes'));
INSERT INTO mt_meetups (member_id, title, category, description, country, city, place, starts_at, ends_at, capacity, photo_key, status, cancelled_at, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'anas@demo.ftour.invalid'), 'Gagnez 5000 DH par jour : réunion d''information', 'autre', 'Réunion pour présenter une opportunité de revenus rapides. Aucune expérience demandée, écrivez-moi en privé pour avoir l''adresse.', 'Maroc', 'Casablanca', 'Lieu communiqué en privé', (date('now','+5 days') || 'T20:00'), (date('now','+5 days') || 'T21:00'), 50, NULL, 'hidden', NULL, strftime('%Y-%m-%dT%H:%M:%fZ','now','-2880 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-2880 minutes'));
